"use client"

import type { ReactNode } from "react"

import { AppShell } from "@/registry/templates/app-shell-01/app-shell"
import { HeaderStatus } from "@/registry/templates/app-shell-01/header-status"
import { navConfig } from "@/registry/templates/app-shell-01/nav-config"
import { services } from "@/registry/templates/app-shell-01/sample-data"

/**
 * 控制台布局：app/(app) 路由组下的所有页面都会套上这层壳。
 * 导航数据里的图标是函数，不能从服务端组件传给客户端组件，所以这个布局是客户端组件。
 * 把 brand、user、onSignOut 换成你自己的数据与登录逻辑。
 * 侧栏折叠状态的首帧脚本由 AppShell 自动注入，这里和根布局都不需要额外接线。
 */
export default function AppLayout({ children }: { children: ReactNode }) {
  return (
    <AppShell
      nav={navConfig}
      brand={{ name: "Acme 控制台", tagline: "企业级监控与运维", href: "/dashboard" }}
      user={{ name: "管理员", email: "admin@example.com" }}
      onSignOut={() => {
        // TODO: 调用你的认证服务退出登录，然后跳转到 /login
      }}
      headerActions={<HeaderStatus services={services} />}
    >
      {children}
    </AppShell>
  )
}

import type { Metadata } from "next"

import { DashboardOverview } from "@/registry/templates/app-shell-01/dashboard-overview"

export const metadata: Metadata = {
  title: "概览",
}

/** 控制台首页：概览仪表盘。按同样的方式在 app/(app)/ 下添加更多页面，它们会自动套上侧栏与顶栏。 */
export default function DashboardPage() {
  return <DashboardOverview />
}

import type { Metadata } from "next"
import { notFound } from "next/navigation"

import { ListPage } from "@/registry/templates/app-shell-01/list-page"
import { navConfig } from "@/registry/templates/app-shell-01/nav-config"
import {
  isModule,
  normalizeHref,
  resolveNav,
} from "@/registry/templates/app-shell-01/nav-types"
import { PageSummary } from "@/registry/templates/app-shell-01/page-summaries"

type Props = { params: Promise<{ slug: string[] }> }

const BASE = "/dashboard"

/** 导航里除概览以外、位于 /dashboard/ 下的全部页面地址 */
function sectionHrefs() {
  const sections = [
    ...navConfig.sections,
    ...(navConfig.footer ? [navConfig.footer] : []),
  ]
  return sections
    .flatMap((section) => section.entries)
    .flatMap((entry) => (isModule(entry) ? entry.items : [entry]))
    .map((item) => normalizeHref(item.href))
    .filter((href) => href.startsWith(`${BASE}/`))
}

/** 只认导航里登记过的地址；其他路径交给 404 */
function resolveSection(slug: string[]) {
  const href = `${BASE}/${slug.join("/")}`
  const active = resolveNav(navConfig, href)
  return active && normalizeHref(active.item.href) === href ? active : undefined
}

export const dynamicParams = false

export function generateStaticParams() {
  return sectionHrefs().map((href) => ({
    slug: href.slice(BASE.length + 1).split("/"),
  }))
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const active = resolveSection((await params).slug)
  return { title: active?.item.label }
}

/**
 * 导航中其余页面的占位实现：按地址找到导航项，显示通用列表页与该页的数据摘要。
 * 开发真实页面时，在 app/(app)/dashboard/ 下新建同名路由即可，具体路由优先于这个兜底页。
 */
export default async function SectionPage({ params }: Props) {
  const active = resolveSection((await params).slug)
  if (!active) notFound()
  return (
    <ListPage
      section={active.trail.at(-2)}
      title={active.item.label}
      description={active.item.description}
      summary={<PageSummary id={active.item.id} />}
    />
  )
}

"use client"

import * as React from "react"
import { usePathname } from "next/navigation"

import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"
import { TooltipProvider } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/registry/hooks/use-controllable-state"

import { AppHeader, type AppShellBrand } from "./app-header"
import { AppShellScript, type AppShellScriptProps } from "./app-shell-script"
import {
  AppShellLabelsProvider,
  DEFAULT_STORAGE_KEY,
  NAV_WIDTH_CLASS,
  NAV_WIDTH_TRANSITION,
  useAppShellLabels,
  type AppShellLabels,
} from "./config"
import type { NavLinkBehavior } from "./nav-link"
import { resolveNav, type NavConfig } from "./nav-types"
import { PrimaryNav } from "./primary-nav"
import { useStoredFlag } from "./use-stored-flag"
import type { AppShellUser } from "./user-menu"
import { WorkspaceMobileNav, WorkspaceSidebar } from "./workspace-sidebar"

type AppShellProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** 导航数据：一级导航 + 二级（工作区）侧栏，见 nav-config.ts */
  nav: NavConfig
  /** 品牌区：名称、Logo、说明与跳转地址 */
  brand?: AppShellBrand
  /** 顶栏右侧的额外操作区，例如「AI 助手」按钮、服务状态 */
  headerActions?: React.ReactNode
  /** 主区域右侧插槽；agent-chat 嵌入面板在空间不足时覆盖显示，高度占满工作区 */
  aside?: React.ReactNode
  /** 当前登录用户，用于顶栏右侧的用户菜单；不传则不显示 */
  user?: AppShellUser
  /** 额外的用户菜单项（DropdownMenuItem），放在「退出登录」之前 */
  userMenu?: React.ReactNode
  /** 点击「退出登录」时的回调 */
  onSignOut?: () => void
  /** 当前地址，用于高亮导航；不传则取 usePathname() */
  activeHref?: string
  /** 传入后拦截导航链接的默认跳转并回调，适合预览 / 单页场景；接入路由时不要传 */
  onNavigate?: (payload: { href: string }) => void
  /**
   * 侧栏是否折叠（受控）；不传则内部维护并记住在 localStorage。
   * 受控时不读写 localStorage、也不注入首帧脚本：想避免首屏闪烁，
   * 请让首次渲染传入的值就是最终状态（例如服务端从 cookie 读取）。
   */
  collapsed?: boolean
  /** 非受控时的初始折叠状态（无本地记录时生效） */
  defaultCollapsed?: boolean
  /** 折叠状态变化时的回调，受控与非受控都会触发 */
  onCollapsedChange?: (collapsed: boolean) => void
  /** 非受控时记住折叠状态的 localStorage 键 */
  storageKey?: string
  /**
   * 是否显示亮暗模式切换（依赖 next-themes）
   * @default true
   */
  themeToggle?: boolean
  /** 覆盖默认文案，见 config.ts 的 DEFAULT_LABELS */
  labels?: Partial<AppShellLabels>
  /** 主区域内容 */
  children: React.ReactNode
}

const defaultBrand: AppShellBrand = { name: "控制台" }

/**
 * 企业控制台布局：固定顶栏 + 可折叠一级导航 + 可选二级工作区侧栏 + 独立滚动的主区域 + 右侧 aside 插槽。
 * 窄屏（< 768px）一级导航变为左侧 Sheet 抽屉，二级导航变为顶栏下方的横向标签条。
 */
function AppShell({
  className,
  nav,
  brand = defaultBrand,
  headerActions,
  aside,
  user,
  userMenu,
  onSignOut,
  activeHref,
  onNavigate,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  storageKey = DEFAULT_STORAGE_KEY,
  themeToggle = true,
  labels,
  children,
  ...props
}: AppShellProps) {
  const text = useAppShellLabels(labels)
  const pathname = usePathname()
  const currentHref = activeHref ?? pathname
  const active = React.useMemo(
    () => resolveNav(nav, currentHref),
    [nav, currentHref],
  )

  // 非受控时折叠状态来自 localStorage（水合安全）；受控时完全由外部决定
  const [stored, setStored] = useStoredFlag(storageKey, defaultCollapsed)
  const [collapsed, setCollapsed] = useControllableState({
    prop: collapsedProp ?? stored,
    defaultProp: defaultCollapsed,
    onChange: (next) => {
      if (collapsedProp === undefined) setStored(next)
      onCollapsedChange?.(next)
    },
  })
  const [mobileOpen, setMobileOpen] = React.useState(false)
  // 只有用户点击折叠后才开启宽度过渡，首次渲染与水合不播放动画
  const [animate, setAnimate] = React.useState(false)

  const mainRef = React.useRef<HTMLElement>(null)
  React.useEffect(() => {
    mainRef.current?.scrollTo({ top: 0, left: 0 })
  }, [currentHref])

  const navigation = React.useMemo<NavLinkBehavior>(
    () => ({
      intercept: Boolean(onNavigate),
      onNavigate: (payload) => {
        setMobileOpen(false)
        onNavigate?.(payload)
      },
    }),
    [onNavigate],
  )

  const group = active?.module

  return (
    <TooltipProvider>
      <AppShellLabelsProvider labels={text}>
        <Sheet open={mobileOpen} onOpenChange={setMobileOpen}>
          <div
            data-slot="app-shell"
            data-collapsed={collapsed ? "" : undefined}
            data-animate={animate ? "" : undefined}
            data-has-aside={aside ? "" : undefined}
            data-has-workspace={group ? "" : undefined}
            className={cn(
              "group/app-shell flex h-svh flex-col overflow-hidden bg-muted/35 text-foreground",
              className,
            )}
            // 首帧脚本会在水合前改写 data-collapsed，以 DOM 为准
            suppressHydrationWarning
            {...props}
          >
            {/* 受控时折叠状态由外部决定，不能让脚本用本地记录覆盖 */}
            {collapsedProp === undefined ? (
              <AppShellScript storageKey={storageKey} />
            ) : null}
            <a
              href="#main-content"
              className="sr-only focus:not-sr-only focus:fixed focus:top-4 focus:left-4 focus:z-[100] focus:rounded-md focus:bg-background focus:px-4 focus:py-2 focus:text-sm focus:font-medium focus:shadow-lg focus:outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
            >
              {text.skipToContent}
            </a>
            <AppHeader
              brand={brand}
              collapsed={collapsed}
              onToggleCollapsed={() => {
                setAnimate(true)
                setCollapsed(!collapsed)
              }}
              trail={active?.trail ?? []}
              actions={headerActions}
              themeToggle={themeToggle}
              user={user}
              userMenu={userMenu}
              onSignOut={onSignOut}
              navigation={navigation}
              labels={labels}
            />
            {group ? (
              <WorkspaceMobileNav
                module={group}
                activeId={active?.item.id}
                navigation={navigation}
                labels={labels}
              />
            ) : null}
            <div className="flex min-h-0 flex-1">
              <aside
                data-slot="app-shell-sidebar"
                data-collapsed={collapsed ? "" : undefined}
                className={cn(
                  "hidden shrink-0 border-r border-sidebar-border bg-sidebar min-[800px]:flex",
                  NAV_WIDTH_CLASS.sidebar,
                  NAV_WIDTH_TRANSITION,
                )}
              >
                <PrimaryNav
                  config={nav}
                  active={active}
                  collapsed={collapsed}
                  navigation={navigation}
                  labels={labels}
                />
              </aside>
              {group ? (
                <WorkspaceSidebar
                  module={group}
                  activeId={active?.item.id}
                  navigation={navigation}
                  labels={labels}
                />
              ) : null}
              <div
                data-slot="app-shell-workspace"
                className="@container/workspace relative flex min-h-0 min-w-0 flex-1"
              >
                <main
                  data-slot="app-shell-main"
                  id="main-content"
                  ref={mainRef}
                  tabIndex={-1}
                  aria-label={text.mainContent}
                  className="@container/main min-h-0 min-w-0 flex-1 overflow-y-auto bg-background outline-none"
                >
                  {children}
                </main>
                {/* 留足主区域 600px；助手最大拖拽宽度 640px，空间不足时覆盖显示。 */}
                <div className="contents [&>[data-mode=embedded]]:absolute [&>[data-mode=embedded]]:inset-y-0 [&>[data-mode=embedded]]:right-0 [&>[data-mode=embedded]]:z-30 [&>[data-mode=embedded]]:max-w-full [&>[data-mode=embedded]]:shadow-xl @min-[1240px]/workspace:[&>[data-mode=embedded]]:relative @min-[1240px]/workspace:[&>[data-mode=embedded]]:shadow-none">
                  {aside}
                </div>
              </div>
            </div>
            <SheetContent
              side="left"
              className="gap-0 p-0 data-[side=left]:w-[280px] data-[side=left]:sm:max-w-[280px]"
            >
              <SheetHeader className="border-b border-border px-4 py-3">
                <SheetTitle className="text-sm">
                  {text.mainNavigation}
                </SheetTitle>
                <SheetDescription className="sr-only">
                  {text.mainNavigationDescription}
                </SheetDescription>
              </SheetHeader>
              <div className="flex min-h-0 flex-1 bg-sidebar">
                <PrimaryNav
                  config={nav}
                  active={active}
                  navigation={navigation}
                  labels={labels}
                />
              </div>
            </SheetContent>
          </div>
        </Sheet>
      </AppShellLabelsProvider>
    </TooltipProvider>
  )
}

export { AppShell, AppShellScript }
export type { AppShellBrand, AppShellProps, AppShellScriptProps, AppShellUser }

"use client"

import * as React from "react"
import { PanelLeftIcon } from "lucide-react"

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import { SheetTrigger } from "@/components/ui/sheet"
import { cn } from "@/lib/utils"

import {
  formatLabel,
  NAV_WIDTH_CLASS,
  NAV_WIDTH_TRANSITION,
  useAppShellLabels,
  type AppShellLabels,
} from "./config"
import { NavLink, type NavLinkBehavior } from "./nav-link"
import { ThemeToggle } from "./theme-toggle"
import { UserMenu, type AppShellUser } from "./user-menu"

type AppShellBrand = {
  name: string
  /** Logo 节点，建议 32×32 的 SVG / 图片；不传则用名称首字生成方块 */
  logo?: React.ReactNode
  /** 名称下方的一行说明，仅在侧栏展开的桌面端显示 */
  tagline?: string
  /** 点击品牌区跳转的地址，默认 "/" */
  href?: string
}

type AppHeaderProps = Omit<React.ComponentProps<"header">, "children"> & {
  brand: AppShellBrand
  collapsed: boolean
  onToggleCollapsed: () => void
  /** 面包屑：分组 → 模块 → 页面 */
  trail: string[]
  actions?: React.ReactNode
  themeToggle: boolean
  user?: AppShellUser
  userMenu?: React.ReactNode
  onSignOut?: () => void
  navigation?: NavLinkBehavior
  labels?: Partial<AppShellLabels>
}

/** 固定顶栏：左侧品牌区（宽度与一级导航对齐）+ 折叠按钮 + 面包屑 + 右侧操作区。 */
function AppHeader({
  className,
  brand,
  collapsed,
  onToggleCollapsed,
  trail,
  actions,
  themeToggle,
  user,
  userMenu,
  onSignOut,
  navigation,
  labels,
  ...props
}: AppHeaderProps) {
  const text = useAppShellLabels(labels)
  const toggleLabel = collapsed ? text.expandSidebar : text.collapseSidebar
  return (
    <header
      data-slot="app-shell-header"
      data-collapsed={collapsed ? "" : undefined}
      className={cn(
        "relative z-30 shrink-0 border-b border-sidebar-border bg-background",
        className
      )}
      {...props}
    >
      <div className="flex h-14 items-center">
        <div
          className={cn(
            "h-full shrink-0 border-r border-sidebar-border bg-sidebar px-3 sm:px-4",
            NAV_WIDTH_CLASS.brand,
            NAV_WIDTH_TRANSITION
          )}
        >
          <NavLink
            href={brand.href ?? "/"}
            navigation={navigation}
            aria-label={formatLabel(text.brandHome, brand.name)}
            className={cn(
              "flex h-full min-w-0 items-center gap-2.5 rounded-md outline-none focus-visible:ring-3 focus-visible:ring-ring/50 max-[800px]:justify-center group-data-[collapsed]/app-shell:justify-center"
            )}
          >
            <span className="flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-lg">
              {brand.logo ?? (
                <span
                  aria-hidden="true"
                  className="flex size-full items-center justify-center bg-primary text-sm font-semibold text-primary-foreground"
                >
                  {brand.name.trim().slice(0, 1).toUpperCase()}
                </span>
              )}
            </span>
            <span className="hidden min-w-0 leading-tight min-[800px]:block min-[800px]:group-data-[collapsed]/app-shell:hidden">
              <span className="block truncate text-sm font-semibold">
                {brand.name}
              </span>
              {brand.tagline ? (
                <span className="block truncate text-[11px] text-muted-foreground">
                  {brand.tagline}
                </span>
              ) : null}
            </span>
          </NavLink>
        </div>

        <div className="flex min-w-0 flex-1 items-center gap-1.5 px-3 sm:px-4">
          <SheetTrigger
            render={
              <Button
                variant="ghost"
                size="icon"
                className="-ml-1 min-[800px]:hidden"
                aria-label={text.openNavigation}
              />
            }
          >
            <PanelLeftIcon />
          </SheetTrigger>
          <Button
            variant="ghost"
            size="icon"
            className="-ml-1 hidden min-[800px]:inline-flex"
            onClick={onToggleCollapsed}
            aria-label={toggleLabel}
            aria-expanded={!collapsed}
            title={toggleLabel}
          >
            <PanelLeftIcon />
          </Button>

          {trail.length > 0 ? (
            <Breadcrumb aria-label={text.breadcrumb} className="min-w-0">
              <BreadcrumbList className="flex-nowrap gap-1 overflow-hidden">
                {trail.map((label, index) => {
                  const last = index === trail.length - 1
                  return last ? (
                    <BreadcrumbItem
                      key={`${label}-${index}`}
                      className="min-w-0"
                    >
                      <BreadcrumbPage className="truncate font-semibold">
                        {label}
                      </BreadcrumbPage>
                    </BreadcrumbItem>
                  ) : (
                    // 分隔符本身是 <li>，必须和 BreadcrumbItem 并列，嵌套会触发水合错误
                    <React.Fragment key={`${label}-${index}`}>
                      <BreadcrumbItem className="hidden shrink-0 lg:inline-flex">
                        {label}
                      </BreadcrumbItem>
                      <BreadcrumbSeparator className="hidden shrink-0 lg:flex lg:items-center" />
                    </React.Fragment>
                  )
                })}
              </BreadcrumbList>
            </Breadcrumb>
          ) : null}

          <div className="ml-auto flex shrink-0 items-center gap-1 sm:gap-1.5">
            {actions}
            {themeToggle ? <ThemeToggle labels={labels} /> : null}
            {user ? (
              <UserMenu user={user} onSignOut={onSignOut} labels={labels}>
                {userMenu}
              </UserMenu>
            ) : null}
          </div>
        </div>
      </div>
    </header>
  )
}

export { AppHeader }
export type { AppHeaderProps, AppShellBrand }

import { DEFAULT_STORAGE_KEY } from "./config"

type AppShellScriptProps = {
  /** 与 AppShell 的 `storageKey` 保持一致 */
  storageKey?: string
}

/**
 * 首帧脚本：在浏览器解析 HTML 时（早于首次绘制与水合）读取 localStorage，
 * 把折叠状态写到所在元素（AppShell 根元素）的 `data-collapsed`，
 * 侧栏宽度、图标栏等样式据此在水合前就是正确状态，刷新不再闪烁。
 * 没有本地记录时不动，保持服务端渲染的 `defaultCollapsed`。
 *
 * 必须作为 AppShell 根元素的子节点渲染（AppShell 已自动放好），
 * 脚本通过 `document.currentScript.parentElement` 找到根元素。
 */
function AppShellScript({ storageKey = DEFAULT_STORAGE_KEY }: AppShellScriptProps) {
  // 键里的 "<" 转义，防止提前闭合 <script>
  const key = JSON.stringify(storageKey).replace(/</g, "\\u003c")
  const html = `(function(){try{var v=localStorage.getItem(${key});if(v===null)return;var e=document.currentScript.parentElement;if(v==="1")e.setAttribute("data-collapsed","");else e.removeAttribute("data-collapsed")}catch(_){}})()`

  return (
    <script
      data-slot="app-shell-script"
      // 服务端输出可执行脚本；客户端渲染（路由跳转进来）时改为 text/plain，
      // 避免 React 对 <script> 的开发警告——此时 React 自己按 localStorage 渲染，无需脚本
      type={typeof window === "undefined" ? "text/javascript" : "text/plain"}
      suppressHydrationWarning
      dangerouslySetInnerHTML={{ __html: html }}
    />
  )
}

export { AppShellScript }
export type { AppShellScriptProps }

"use client"

import * as React from "react"
import { ChevronRightIcon } from "lucide-react"

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import { useAppShellLabels, type AppShellLabels } from "./config"
import { NavLink, type NavLinkBehavior } from "./nav-link"
import {
  isModule,
  moduleHref,
  type NavConfig,
  type NavEntry,
  type NavSection,
  type ResolvedNav,
} from "./nav-types"

type PrimaryNavProps = Omit<React.ComponentProps<"nav">, "children"> & {
  config: NavConfig
  /** 当前页面对应的导航位置，由 resolveNav 得到 */
  active?: ResolvedNav
  /**
   * 图标栏模式：只显示图标，名称放到 Tooltip 与读屏文本里。
   * 外观由祖先 `.group/app-shell[data-collapsed]` 决定（水合前即生效），
   * 这个 prop 只负责 Tooltip 的开关；抽屉里的导航在 AppShell 之外，始终展开。
   */
  collapsed?: boolean
  navigation?: NavLinkBehavior
  labels?: Partial<AppShellLabels>
}

/** 一级导航：分组标题 + 条目；模块条目指向其第一个子项，选中时左侧出现二级侧栏。 */
function PrimaryNav({
  className,
  config,
  active,
  collapsed = false,
  navigation,
  labels,
  ...props
}: PrimaryNavProps) {
  const text = useAppShellLabels(labels)

  function renderEntry(entry: NavEntry) {
    const isGroup = isModule(entry)
    const selected = isGroup
      ? active?.module?.id === entry.id
      : active?.item.id === entry.id
    const Icon = entry.icon
    const badge = isGroup ? undefined : entry.badge
    const link = (
      <NavLink
        data-slot="app-shell-nav-item"
        data-active={selected ? "" : undefined}
        href={isGroup ? moduleHref(entry) : entry.href}
        navigation={navigation}
        aria-current={selected ? (isGroup ? "true" : "page") : undefined}
        className={cn(
          "relative flex h-10 w-full min-w-0 items-center gap-3 rounded-md px-3 text-sm transition-colors outline-none group-data-[collapsed]/app-shell:justify-center group-data-[collapsed]/app-shell:px-2 focus-visible:ring-3 focus-visible:ring-ring/50 motion-reduce:transition-none",
          selected
            ? "bg-primary/10 font-medium text-sidebar-foreground shadow-[inset_3px_0_0_var(--primary)]"
            : "text-sidebar-foreground/70 hover:bg-primary/5 hover:text-sidebar-foreground"
        )}
      >
        <Icon className="size-4 shrink-0" aria-hidden="true" />
        {/* 折叠与否只靠 CSS 切换，水合前就是正确的外观；折叠时名称保留为读屏文本 */}
        <span className="min-w-0 flex-1 truncate group-data-[collapsed]/app-shell:sr-only">
          {entry.label}
        </span>
        {badge !== undefined ? (
          <>
            <span className="rounded-full bg-primary/10 px-1.5 text-[11px] leading-5 font-medium text-primary tabular-nums group-data-[collapsed]/app-shell:hidden">
              {badge}
            </span>
            <span
              aria-hidden="true"
              className="absolute top-2 right-2 hidden size-1.5 rounded-full bg-primary group-data-[collapsed]/app-shell:block"
            />
          </>
        ) : null}
        {isGroup ? (
          <ChevronRightIcon
            className="size-3 shrink-0 opacity-40 group-data-[collapsed]/app-shell:hidden"
            aria-hidden="true"
          />
        ) : null}
      </NavLink>
    )
    return (
      <li key={entry.id}>
        {/* 始终包一层 Tooltip，仅折叠时启用，避免折叠切换时重新挂载链接 */}
        <Tooltip disabled={!collapsed}>
          <TooltipTrigger render={link} />
          <TooltipContent side="right">{entry.label}</TooltipContent>
        </Tooltip>
      </li>
    )
  }

  function renderSection(section: NavSection) {
    return (
      <section key={section.id} aria-label={section.label}>
        <h2
          className="flex h-8 items-center px-3 text-[11px] font-medium text-sidebar-foreground/50 group-data-[collapsed]/app-shell:sr-only"
        >
          {section.label}
        </h2>
        <ul className="flex flex-col gap-1">
          {section.entries.map(renderEntry)}
        </ul>
      </section>
    )
  }

  return (
    <nav
      data-slot="app-shell-primary-nav"
      data-collapsed={collapsed ? "" : undefined}
      aria-label={text.mainNavigation}
      className={cn("flex h-full min-h-0 flex-1 flex-col", className)}
      {...props}
    >
      <div className="flex min-h-0 flex-1 flex-col gap-6 overflow-y-auto px-2 py-4">
        {config.sections.map(renderSection)}
      </div>
      {config.footer ? (
        <div className="shrink-0 border-t border-sidebar-border px-2 py-3">
          {renderSection(config.footer)}
        </div>
      ) : null}
    </nav>
  )
}

