}

/**
 * 范围切换条（如「全局总览 / 应用 A / 应用 B」）：用分段选择实现。
 * 它切换的是同一页内容的数据范围，没有对应的面板，所以用单选语义而不是 tab；窄屏可横向滚动。
 */
function PageTabs({
  className,
  tabs,
  value,
  onValueChange,
  trailing,
  labels,
  ...props
