        <SegmentedControl
          size="sm"
          aria-label={text.scopeSwitch}
          className="w-max min-w-max"
          value={value}
          onValueChange={onValueChange}
          options={tabs.map(({ value: tab, label, icon: Icon }) => ({
            value: tab,
            label,
            icon: Icon ? <Icon /> : undefined,
