}

type PageFrameProps = Omit<React.ComponentProps<"div">, "title"> &
  Pick<PageHeaderProps, "title" | "description" | "section" | "actions"> & {
    /** 标题栏下方的标签条，通常是 <PageTabs /> */
    tabs?: React.ReactNode
    /** 标题栏下方的工具栏，通常是 <PageToolbar /> */
    toolbar?: React.ReactNode
