"use client"

import * as React from "react"
import { ChevronLeftIcon, ChevronRightIcon, SearchIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

import { useAppShellLabels, type AppShellLabels } from "./config"

type PageToolbarProps = Omit<React.ComponentProps<"section">, "children"> & {
  total: number
  page: number
  pageSize: number
  onPageChange: (page: number) => void
  search?: string
  onSearchChange?: (value: string) => void
  /** 搜索框的无障碍名称与占位文字，默认取 labels.search */
  searchLabel?: string
  /** 搜索框旁边的筛选控件，例如 Select、Popover */
  filters?: React.ReactNode
  labels?: Partial<AppShellLabels>
}

/**
 * 列表页工具栏：总数 + 翻页 + 搜索 + 自定义筛选项（filters 插槽）。
 * 状态完全受控，数据请求与过滤逻辑由页面自己负责。
 */
function PageToolbar({
  className,
  total,
  page,
  pageSize,
  onPageChange,
  search,
  onSearchChange,
  searchLabel,
  filters,
  labels,
  ...props
}: PageToolbarProps) {
  const text = useAppShellLabels(labels)
  const totalPages = Math.max(1, Math.ceil(total / pageSize))
  const searchName = searchLabel ?? text.search
  return (
    <section
      data-slot="app-shell-page-toolbar"
      aria-label={text.pageToolbar}
      className={cn(
        "flex min-h-14 shrink-0 flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-4 py-3 sm:px-6",
        className
      )}
      {...props}
    >
      <div className="flex items-center gap-3">
        <span className="text-xs font-medium tabular-nums">
          {total} {text.totalUnit}
        </span>
        <div className="flex items-center gap-1">
          <Button
            variant="outline"
            size="icon-sm"
            aria-label={text.previousPage}
            disabled={page <= 1}
            onClick={() => onPageChange(page - 1)}
          >
            <ChevronLeftIcon />
          </Button>
          <span className="min-w-14 text-center text-xs text-muted-foreground tabular-nums">
            {page} / {totalPages}
          </span>
          <Button
            variant="outline"
            size="icon-sm"
            aria-label={text.nextPage}
            disabled={page >= totalPages}
            onClick={() => onPageChange(page + 1)}
          >
            <ChevronRightIcon />
          </Button>
        </div>
      </div>
      <div className="flex w-full min-w-0 flex-wrap items-center gap-2 sm:w-auto">
        {onSearchChange ? (
          <div className="relative min-w-36 flex-1 sm:w-64 sm:flex-none">
            <SearchIcon
              aria-hidden="true"
              className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground"
            />
            <Input
              type="search"
              value={search ?? ""}
              onChange={(event) => onSearchChange(event.target.value)}
              aria-label={searchName}
              placeholder={`${searchName}…`}
              className="pl-8 text-xs md:text-xs"
            />
          </div>
        ) : null}
        {filters}
      </div>
    </section>
  )
}

export { PageToolbar }
export type { PageToolbarProps }

"use client"

import * as React from "react"
import {
  ActivityIcon,
  AlertTriangleIcon,
  CheckCircle2Icon,
  CircleDashedIcon,
  XCircleIcon,
  type LucideIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"

import { formatLabel, useAppShellLabels, type AppShellLabels } from "./config"

type ServiceState = "healthy" | "warning" | "unavailable" | "unknown"

type ServiceStatus = {
  id: string
  label: string
  state: ServiceState
  detail?: string
}

type HeaderStatusProps = {
  services: ServiceStatus[]
  /** 最近一次检查时间的展示文字，例如「14:32:05」 */
  checkedAt?: string
  className?: string
  labels?: Partial<AppShellLabels>
}

// 状态靠「图标 + 文字」区分，颜色只用主题变量，换颜色主题后依然可辨
const stateStyles: Record<
  ServiceState,
  { label: keyof AppShellLabels; icon: LucideIcon; className: string }
> = {
  healthy: {
    label: "stateHealthy",
    icon: CheckCircle2Icon,
    className: "text-primary",
  },
  warning: {
    label: "stateWarning",
    icon: AlertTriangleIcon,
    className: "text-foreground",
  },
  unavailable: {
    label: "stateUnavailable",
    icon: XCircleIcon,
    className: "text-destructive",
  },
  unknown: {
    label: "stateUnknown",
    icon: CircleDashedIcon,
    className: "text-muted-foreground",
  },
}

const severity: ServiceState[] = ["unavailable", "warning", "unknown", "healthy"]

/** 顶栏服务状态：按钮显示整体状态，弹层列出各服务。数据由外部传入（轮询、SSE 等自行实现）。 */
function HeaderStatus({
  services,
  checkedAt,
  className,
  labels,
}: HeaderStatusProps) {
  const text = useAppShellLabels(labels)
  const overall =
    severity.find((state) => services.some((s) => s.state === state)) ??
    "unknown"
  const Overall = stateStyles[overall]
  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            variant="ghost"
            className={cn("gap-1.5 px-2 text-muted-foreground", className)}
            aria-label={formatLabel(
              text.serviceStatusAria,
              text[Overall.label]
            )}
          />
        }
      >
        <span className="relative flex size-4 items-center justify-center">
          <ActivityIcon aria-hidden="true" />
          <Overall.icon
            aria-hidden="true"
            className={cn(
              "absolute -top-1 -right-1 size-2.5 rounded-full bg-background",
              Overall.className
            )}
          />
        </span>
        <span className="hidden text-xs xl:inline">{text.serviceStatus}</span>
      </PopoverTrigger>
      <PopoverContent
        data-slot="app-shell-header-status"
        align="end"
        className="w-72 max-w-[calc(100vw-1rem)]"
      >
        <p className="text-sm font-medium">{text.serviceStatus}</p>
        <ul className="divide-y divide-border">
          {services.map((service) => {
            const state = stateStyles[service.state]
            return (
              <li key={service.id} className="py-2 first:pt-0 last:pb-0">
                <div className="flex items-center justify-between gap-2 text-xs">
                  <span>{service.label}</span>
                  <span
                    className={cn("flex items-center gap-1.5", state.className)}
                  >
                    <state.icon className="size-3.5" aria-hidden="true" />
                    {text[state.label]}
                  </span>
                </div>
                {service.detail ? (
                  <p className="mt-1 text-xs leading-5 text-muted-foreground">
                    {service.detail}
                  </p>
                ) : null}
              </li>
            )
          })}
        </ul>
        {checkedAt ? (
          <p className="text-[11px] text-muted-foreground">
            {formatLabel(text.checkedAt, checkedAt)}
          </p>
        ) : null}
      </PopoverContent>
    </Popover>
  )
}

