    </section>
  )
}

/** 达标率越低颜色越重：不低于 95% 用绿色，否则琥珀。 */
function sloTone(value: number): DataTone {
  return value >= 95 ? "green" : "amber"
}

/** 接口探测：耗时分布直方图 + 三档分位的 SLO 达标环。 */
function InterfacesSummary() {
  const text = useAppShellLabels()

  return (
    <section
      data-slot="app-shell-interfaces-summary"
      aria-label={text.pageSummary}
      className="grid gap-4 @3xl:grid-cols-3"
    >
      <ChartCard className="@3xl:col-span-2">
        <SummaryHeader
          title={text.latencyDistribution}
          description={text.latencyDistributionDescription}
        />
        <ChartCardContent className="flex-1">
          <ChartSeries
            type="bar"
            className="h-full min-h-52"
            data={latencyBuckets}
            xKey="bucket"
            series={[
              {
                key: "count",
                label: text.latencyDistributionSeries,
                tone: "blue",
              },
            ]}
            label={text.latencyDistributionLabel}
          />
        </ChartCardContent>
      </ChartCard>
      <ChartCard>
        <SummaryHeader
          title={text.sloAttainment}
          description={text.sloAttainmentDescription}
        />
        <ChartCardContent className="flex flex-1 items-center justify-between gap-2">
          {sloTargets.map((slo) => (
            <div
              key={slo.id}
              className="flex flex-col items-center gap-3 text-center"
            >
              <MiniRing
                value={slo.value}
                size={64}
                thickness={11}
                tone={sloTone(slo.value)}
                label={formatLabel(text.sloRingLabel, {
                  name: slo.label,
                  percent: percent(slo.value),
                })}
              />
              <div className="flex flex-col gap-0.5">
                <span className="text-sm font-medium">{slo.label}</span>
                <span className="text-xs whitespace-nowrap text-muted-foreground">
                  {slo.target}
                </span>
              </div>
            </div>
          ))}
        </ChartCardContent>
      </ChartCard>
    </section>
  )
}

/** 资源使用率越高颜色越重：85% 以上玫红、70% 以上琥珀，其余用传入的基础色。 */
function usageTone(value: number, base: DataTone): DataTone {
  return value >= 85 ? "rose" : value >= 70 ? "amber" : base
}

/** 节点监控：每个区域一张卡片，两个进度环分别是 CPU 与内存使用率。 */
function NodesSummary() {
  const text = useAppShellLabels()

  return (
    <section
      data-slot="app-shell-nodes-summary"
      aria-label={text.nodeResources}
      className="grid gap-4 @min-[480px]:grid-cols-2 @min-[960px]:grid-cols-4"
    >
      {nodeGroups.map((node) => {
        const healthy =
          node.online === node.total && Math.max(node.cpu, node.memory) < 70
        const rings = [
          { id: "cpu", name: text.nodeCpu, value: node.cpu, base: "blue" },
          {
            id: "memory",
            name: text.nodeMemory,
            value: node.memory,
            base: "violet",
          },
        ] as const
        return (
          <StatCard key={node.id}>
            <StatHeader>
              <StatLabel>{node.name}</StatLabel>
              <StatBadge status={healthy ? "ok" : "watch"}>
                {healthy ? text.stateHealthy : text.stateWarning}
              </StatBadge>
            </StatHeader>
            <div className="flex items-start justify-around gap-3 py-2">
              {rings.map((ring) => (
                <div
                  key={ring.id}
                  className="flex flex-col items-center gap-2 text-xs text-muted-foreground"
                >
                  <MiniRing
                    value={ring.value}
                    size={68}
                    thickness={11}
                    tone={usageTone(ring.value, ring.base)}
                    label={formatLabel(text.nodeRingLabel, {
                      name: node.name,
                      metric: ring.name,
                      percent: percent(ring.value),
                    })}
                  >
                    <span className="text-xs font-semibold text-foreground">
                      {percent(ring.value)}
                    </span>
                  </MiniRing>
                  {ring.name}
                </div>
              ))}
            </div>
            <StatMeta>
              <span>
                {formatLabel(text.nodeOnline, {
                  online: node.online,
                  total: node.total,
                })}
              </span>
            </StatMeta>
          </StatCard>
        )
      })}
    </section>
  )
}

/** 事件与异常：按级别堆叠的事件趋势 + 异常事件的处理进度。 */
function EventsSummary() {
  const text = useAppShellLabels()
  const errors = eventVolume.reduce((sum, row) => sum + row.error, 0)
  const warnings = eventVolume.reduce((sum, row) => sum + row.warning, 0)
  const recoveredRatio = (resolution.recovered / errors) * 100

  return (
    <section
      data-slot="app-shell-events-summary"
      aria-label={text.pageSummary}
      className="grid gap-4 @3xl:grid-cols-3"
    >
      <ChartCard className="@3xl:col-span-2">
        <SummaryHeader
          title={text.eventsTrend}
          description={text.eventsTrendDescription}
        >
          <ChartMetrics>
            <ChartMetric label={text.eventsTotal} value={errors + warnings} />
            <ChartMetric label={text.eventError} value={errors} tone="rose" />
            <ChartMetric
              label={text.eventWarning}
              value={warnings}
              tone="amber"
            />
          </ChartMetrics>
        </SummaryHeader>
        <ChartCardContent className="flex-1">
          <ChartSeries
            type="bar"
            stacked
            className="h-full min-h-52"
            data={eventVolume}
            xKey="hour"
            series={[
              { key: "error", label: text.eventError, tone: "rose" },
              { key: "warning", label: text.eventWarning, tone: "amber" },
            ]}
            label={text.eventsTrendLabel}
          />
        </ChartCardContent>
      </ChartCard>
      <ChartCard>
        <SummaryHeader
          title={text.resolution}
          description={text.resolutionDescription}
        />
        <ChartCardContent className="flex flex-1 flex-col items-center justify-center gap-6">
          <MiniRing
            value={recoveredRatio}
            size={128}
            thickness={9}
            tone="green"
            label={formatLabel(text.resolutionLabel, {
              percent: percent(recoveredRatio),
            })}
          >
            <span className="text-2xl font-semibold">
              {percent(recoveredRatio)}
            </span>
            <span className="text-[11px] text-muted-foreground">
              {text.resolutionRecovered}
            </span>
          </MiniRing>
          <ChartMetrics>
            <ChartMetric
              label={text.resolutionRecovered}
              value={resolution.recovered}
              tone="green"
            />
            <ChartMetric
              label={text.resolutionInProgress}
              value={resolution.inProgress}
              tone="amber"
            />
            <ChartMetric
              label={text.resolutionPending}
              value={resolution.pending}
              tone="rose"
            />
          </ChartMetrics>
        </ChartCardContent>
      </ChartCard>
    </section>
  )
}

/** 按导航项 id 取对应页面的数据摘要；没有定制摘要的页面返回 null。 */
function PageSummary({ id }: { id: string }) {
  switch (id) {
    case "records":
      return <RecordsSummary />
    case "interfaces":
      return <InterfacesSummary />
    case "nodes":
      return <NodesSummary />
    case "events":
      return <EventsSummary />
    default:
      return null
  }
}

export {
  EventsSummary,
  InterfacesSummary,
  NodesSummary,
  PageSummary,
  RecordsSummary,
}

"use client"

import { formatStat, type DataTone } from "@/registry/lib/data-display"
import {
  ChartCard,
  ChartCardContent,
  ChartCardDescription,
  ChartCardHeader,
  ChartCardTitle,
  ChartLegendGrid,
} from "@/registry/ui/chart-card/chart-card"
import { MiniDonut } from "@/registry/ui/mini-chart/mini-chart"

type DistributionSegment = {
  label: string
  value: number
  tone: DataTone
}

type DistributionCardProps = {
  title: string
  description: string
  segments: readonly DistributionSegment[]
  /** 环中央合计数字下方的小字，如「总请求」 */
  totalLabel: string
  /** 读屏名称，描述这张环形图表示什么 */
  ariaLabel: string
  className?: string
}

/** 占比卡片：环形图中央是合计，下方的图例格给出各分类的占比。概览的状态码分布与拨测的异常原因共用。 */
function DistributionCard({
  title,
  description,
  segments,
  totalLabel,
  ariaLabel,
  className,
}: DistributionCardProps) {
  const total = segments.reduce((sum, item) => sum + item.value, 0)

  return (
    <ChartCard data-slot="app-shell-distribution-card" className={className}>
      <ChartCardHeader>
        <div className="flex flex-col gap-1">
          <ChartCardTitle>{title}</ChartCardTitle>
          <ChartCardDescription>{description}</ChartCardDescription>
        </div>
      </ChartCardHeader>
      <ChartCardContent className="flex flex-1 flex-col items-center justify-center gap-6">
        <MiniDonut
          size={136}
          thickness={26}
          segments={segments.map(({ label, value, tone }) => ({
            label,
            value,
            tone,
          }))}
          label={ariaLabel}
        >
          <span className="text-lg font-semibold">{formatStat(total)}</span>
          <span className="text-[11px] text-muted-foreground">{totalLabel}</span>
        </MiniDonut>
        <ChartLegendGrid
          className="w-full"
          items={segments.map(({ label, value, tone }) => ({
            label,
            tone,
            value: formatStat((value / total) * 100, {
              style: "percent",
              digits: 1,
            }),
          }))}
        />
      </ChartCardContent>
    </ChartCard>
  )
}

export { DistributionCard }
export type { DistributionCardProps, DistributionSegment }

"use client"

import { formatStat } from "@/registry/lib/data-display"
import {
  ChartCard,
  ChartCardContent,
  ChartCardDescription,
  ChartCardFooter,
  ChartCardHeader,
  ChartCardTitle,
  ChartGauge,
  ChartMetric,
  ChartMetrics,
  ChartRanking,
} from "@/registry/ui/chart-card/chart-card"

import { formatLabel, useAppShellLabels } from "./config"
import { DistributionCard } from "./distribution-card"
import { errorBudget, slowestEndpoints, statusCodes } from "./sample-data"

type CardProps = { className?: string }

/** 百分比文字：可用率这类接近 100 的数值保留两位小数 */
const percent = (value: number, digits = 0) =>
  formatStat(value, { style: "percent", digits })

/** 错误预算：刻度仪表显示 30 天窗口里还剩多少，底部写明已消耗的分钟数。 */
function ErrorBudgetCard({ className }: CardProps) {
  const text = useAppShellLabels()
  const remaining = Math.round(
    (1 - errorBudget.usedMinutes / errorBudget.totalMinutes) * 100,
  )

  return (
    <ChartCard data-slot="app-shell-error-budget" className={className}>
      <ChartCardHeader>
        <div className="flex flex-col gap-1">
          <ChartCardTitle>{text.errorBudget}</ChartCardTitle>
          <ChartCardDescription>
            {formatLabel(text.errorBudgetDescription, {
              target: percent(errorBudget.target, 2),
            })}
          </ChartCardDescription>
        </div>
      </ChartCardHeader>
      <ChartCardContent className="flex flex-1 flex-col items-center justify-center gap-5">
        <ChartGauge
          value={remaining}
          tone="green"
          caption={text.errorBudgetRemaining}
          className="size-40"
          label={formatLabel(text.errorBudgetLabel, {
            percent: percent(remaining),
          })}
        />
        <ChartMetrics>
          <ChartMetric
            label={text.errorBudgetTarget}
            value={percent(errorBudget.target, 2)}
          />
          <ChartMetric
            label={text.errorBudgetCurrent}
            value={percent(errorBudget.current, 2)}
            tone="green"
          />
        </ChartMetrics>
      </ChartCardContent>
      <ChartCardFooter>
        {formatLabel(text.errorBudgetUsed, {
          used: errorBudget.usedMinutes,
          total: errorBudget.totalMinutes,
        })}
      </ChartCardFooter>
    </ChartCard>
  )
}

/** 状态码分布：环形图中央放总请求数，旁边的图例格给出各类占比。 */
function StatusCodeCard({ className }: CardProps) {
  const text = useAppShellLabels()
  const total = formatStat(statusCodes.reduce((sum, item) => sum + item.value, 0))

  return (
    <DistributionCard
      className={className}
      title={text.statusCodes}
      description={text.statusCodesDescription}
      segments={statusCodes}
      totalLabel={text.statusCodesTotal}
      ariaLabel={formatLabel(text.statusCodesLabel, { total })}
    />
  )
}

/** 越慢颜色越重：超过 1 s 用玫红、超过 500 ms 用琥珀，其余用蓝色。 */
function slownessTone(latency: number) {
  return latency > 1000 ? "rose" : latency > 500 ? "amber" : "blue"
}

/** 最慢接口排行：横向排名条，条末是 P95 耗时。 */
function SlowestEndpointsCard({ className }: CardProps) {
  const text = useAppShellLabels()

  return (
    <ChartCard data-slot="app-shell-slowest-endpoints" className={className}>
      <ChartCardHeader>
        <div className="flex flex-col gap-1">
          <ChartCardTitle>{text.slowestEndpoints}</ChartCardTitle>
          <ChartCardDescription>
            {text.slowestEndpointsDescription}
          </ChartCardDescription>
        </div>
      </ChartCardHeader>
      <ChartCardContent className="flex flex-1 flex-col justify-center">
        <ChartRanking
          items={slowestEndpoints.map(({ label, value }) => ({
            label,
            value,
            tone: slownessTone(value),
          }))}
          // 默认视口 lg 起图例并排；卡片只占 2/3 宽，改为图例在下方，主区域够宽（@5xl）再并排
          className="lg:grid-cols-1 @5xl:grid-cols-2"
          format={{ style: "number", compact: false, digits: 0 }}
          label={text.slowestEndpointsLabel}
        />
      </ChartCardContent>
    </ChartCard>
  )
}

export { ErrorBudgetCard, SlowestEndpointsCard, StatusCodeCard }

"use client"

import { PlusIcon } from "lucide-react"
import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  ChartCard,
  ChartCardContent,
} from "@/registry/ui/chart-card/chart-card"

import { formatLabel, useAppShellLabels } from "./config"
import { EventsTable } from "./dashboard-overview"
import { PageFrame } from "./page-header"
import { PageToolbar } from "./page-toolbar"
import { events } from "./sample-data"

const PAGE_SIZE = 6

/**
 * 通用列表页示例：标题栏 + 工具栏（搜索、翻页）+ 可选的数据摘要 + 表格。其余导航项在演示里都显示它。
 * summary 插槽放在表格上方，通常是该页自己的指标与图表（见 page-summaries.tsx）。
 */
function ListPage({
  title,
  description,
  section,
  summary,
}: {
  title: string
  description?: string
  section?: string
  summary?: React.ReactNode
}) {
  const text = useAppShellLabels()
  const [search, setSearch] = React.useState("")
  const [page, setPage] = React.useState(1)
  const keyword = search.trim().toLowerCase()
  const filtered = events.filter(
    (row) =>
      !keyword ||
      row.app.toLowerCase().includes(keyword) ||
      row.target.toLowerCase().includes(keyword),
  )
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE))
  const current = Math.min(page, totalPages)
  const rows = filtered.slice((current - 1) * PAGE_SIZE, current * PAGE_SIZE)

  return (
    <PageFrame
      data-slot="app-shell-list-page"
      section={section}
      title={title}
      description={description}
      actions={
        <Button>
          <PlusIcon data-icon="inline-start" />
          {text.createAction}
        </Button>
      }
      toolbar={
        <PageToolbar
          total={filtered.length}
          page={current}
          pageSize={PAGE_SIZE}
          onPageChange={setPage}
          search={search}
          onSearchChange={(value) => {
            setSearch(value)
            setPage(1)
          }}
          searchLabel={text.searchEvents}
        />
      }
    >
      {/* 摘要按所在区域的宽度排版：右侧挂着 aside 时主区域变窄，图表会自动改为单列 */}
      {summary ? (
        <div data-slot="app-shell-list-summary" className="@container empty:hidden">
          {summary}
        </div>
      ) : null}
      <ChartCard>
        <ChartCardContent>
          <EventsTable
            rows={rows}
            caption={formatLabel(text.listCaption, { title })}
          />
        </ChartCardContent>
      </ChartCard>
    </PageFrame>
  )
}

export { ListPage }

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }
